            Paragraph(Text("Every new public API is quoted below with the full literal SOURCE context, telescope, body and qualified owner. There are no new structures, inductives, constructors or projections. The sole imported authorities remain FiniteProtectedDualWord.Symbol/Word/Contract, CollapsePair and Sequence; Filling/Certificate/Rows/compileParent remain the original consumer interfaces. All imported record fields are constructed in the source owner, including its private helpers. The quoted section-variable context is literal source, not an assertion that unused variables become elaborated binders. These quotes do not assert emitted telescopes, elaboration, kernel/axiom closure, Scribe/Reg/native acceptance, reports, gates or remote delivery. The unchanged broad geometry and physical/all-plane scope remain open.")),
            Node("pathContract", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef pathContract (m : Nat) (hm : 3 ≤ m) :\n    Contract (ground m) (pathFamily (pathRootPath m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.pathContract\ndef pathContract (m : Nat) (hm : 3 ≤ m) :\n    Contract (ground m) (pathFamily (pathRootPath m hm)) :=\n  maximalContract (pathRootWordData m hm)\n    (by\n      intro S hS U hU hSU\n      apply path_critical_maximal _ (pathRootPath_nodup m hm) S _ U hU hSU\n      simpa only [root_word] using hS)\n    (root_pair_proper m hm)\n\n/-- Exact original path-row root, retaining the fixed ambient labels. -/", DescribeRole.Definition, describeId: "path-contract"),
            Node("pathRoot_rawDual", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem pathRoot_rawDual (m : Nat) (hm : 3 ≤ m) :\n    rawDual (ground m) (pathFamily (pathRootPath m hm)) = pathRoot m hm", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.pathRoot_rawDual\ntheorem pathRoot_rawDual (m : Nat) (hm : 3 ≤ m) :\n    rawDual (ground m) (pathFamily (pathRootPath m hm)) = pathRoot m hm :=\n  root_dual m hm\n\n/-- P04's partial filling is also present in both obstructed classes.\n    The cells are fixed-ground complements, never raw path criticals. -/", DescribeRole.Theorem, describeId: "path-root-raw-dual"),
            Node("pathFilling", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef pathFilling (m : Nat) (hm : 3 ≤ m) : Filling (ground m) (pathRoot m hm)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.pathFilling\ndef pathFilling (m : Nat) (hm : 3 ≤ m) : Filling (ground m) (pathRoot m hm) := by\n  let d := pathContract m hm\n  have hd : rawDual (ground m) (pathFamily (pathRootPath m hm)) = pathRoot m hm :=\n    root_dual m hm\n  have hc := maximal_cells d.protected\n    (by\n      intro T hT\n      have ht := d.protected_subset T hT\n      refine ⟨ht, ?_⟩\n      have hs := (root_independent m hm T).mp ht\n      refine Finset.ssubset_iff_subset_ne.mpr ⟨hs.1, ?_⟩\n      intro he\n      have h2 : secondLabel m hm ∈ T := by rw [he]; simp [ground, secondLabel]\n      let z : Label m := ⟨3, by omega⟩\n      have h3 : z ∈ T := by rw [he]; simp [ground, z]\n      exact hs.2.1 _ h2 z h3 (by simp [secondLabel]) (by simp [z, secondLabel]))\n    (by\n      intro T hT U hU hTU\n      apply path_critical_maximal _ (pathRootPath_nodup m hm) T _ U hU hTU\n      have h := (criticalFaces_mem _ T).mp hT\n      simpa only [d, pathContract, maximalContract, root_word] using h)\n  refine {\n    empty_mem := ?_\n    collar := pathRoot m hm\n    critical := d.protected.image (fun T => ground m \\ T)\n    contains := le_rfl\n    supported := ((rimRows m (by omega)).without (interfaceRow m hm)).root_supported\n    critical_supported := ?_\n    cells := hd ▸ hc\n    main := d.protectedDualWordSequence.cast rfl ?_\n    separate := Sequence.refl _ }\n  · rw [← hd, dual_mem]\n    refine ⟨Finset.empty_subset _, ?_⟩\n    intro h\n    have hi := (root_independent m hm _).mp h\n    simp only [Finset.sdiff_empty] at hi\n    exact hi.2.1 (secondLabel m hm) (by simp [ground, secondLabel])\n      (⟨3, by omega⟩ : Label m) (by simp [ground])\n      (by simp [secondLabel]) (by simp [secondLabel])\n  · intro s hs\n    obtain ⟨T, _, rfl⟩ := Finset.mem_image.mp hs\n    exact Finset.sdiff_subset\n  · change project (rawEndpoint _ _ _ _) = _\n    rw [contract_endpoint d, hd]\n\n/-- Genuine good-residue Gamma, with its no-critical premise derived from m.\n    This is the sufficiency direction, not the Euler necessity theorem. -/", DescribeRole.Definition, describeId: "path-filling"),
            Node("gammaGood", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef gammaGood (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m) :\n    Sequence (project (delta (ground m))) (project (pathRoot m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.gammaGood\ndef gammaGood (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m) :\n    Sequence (project (delta (ground m))) (project (pathRoot m hm)) := by\n  have S := (pathRootWordData m hm).noCritical_unprotected\n    (by simpa only [root_word] using pathRootPath_noCritical m hm hg)\n    (root_pair_proper m hm)\n  exact S.cast rfl (congrArg project (root_dual m hm))\n\n/-- Actual zero-filling Contract on Z, with the forbidden endpoints retained\n    as ghosts. At m=3 and 4 H contains the raw EMPTY critical face. -/", DescribeRole.Definition, describeId: "gamma-good"),
            Node("zeroContract", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef zeroContract (m : Nat) (hm : 3 ≤ m) :\n    Contract (tailGround m hm) (pathFamily (cyclePathTail m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.zeroContract\ndef zeroContract (m : Nat) (hm : 3 ≤ m) :\n    Contract (tailGround m hm) (pathFamily (cyclePathTail m hm)) := by\n  let p := cycleTailWordData m hm\n  let d : Word (tailGround m hm) (pathFamily (cyclePathTail m hm)) := {\n    word := p.word\n    supported := by\n      intro s hs x hx\n      apply (tail_mem m hm x).mpr\n      have ht := p.supported s hs hx\n      exact le_trans (by omega) ((cyclePathTail_vertices m hm x).mp ht).1\n    pair_data := p.pair_data\n    critical_data := p.critical_data\n    partition := p.partition\n    covers := p.covers\n    pair_dependency := p.pair_dependency\n    critical_dependency := p.critical_dependency }\n  exact maximalContract d\n    (by\n      intro S hS U hU hSU\n      apply path_critical_maximal _ (cyclePathTail_nodup m hm) S _ U hU hSU\n      simpa only [d, p, cycleTailWordData, pathWordData_word] using hS)\n    (by\n      intro L v h\n      have hU := d.pair_data L v h\n      have hs := d.supported _ hU.2.1\n      refine Finset.ssubset_iff_subset_ne.mpr ⟨hs, ?_⟩\n      intro he\n      let z : Label m := ⟨3, by omega⟩\n      have hz : z ∈ insert v L := by rw [he]; exact (tail_mem m hm z).mpr (by rfl)\n      have ht := p.supported _ hU.2.1 hz\n      have hn := (cyclePathTail_vertices m hm z).mp ht\n      dsimp [z] at hn\n      omega)\n\n/-- P05 for every m>=3: actual main list, identity standalone collar, and\n    full proper boundaries/absence/antichain on the unchanged Z. -/", DescribeRole.Definition, describeId: "zero-contract"),
            Node("fill0", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef fill0 (m : Nat) (hm : 3 ≤ m) : Filling (tailGround m hm) (A0 m hm)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill0\ndef fill0 (m : Nat) (hm : 3 ≤ m) : Filling (tailGround m hm) (A0 m hm) := by\n  let d := zeroContract m hm\n  have hd := zero_dual m hm\n  have hp : ∀ T ∈ d.protected, T ⊂ tailGround m hm := by\n    intro T hT\n    have ht := d.protected_subset T hT\n    have hs := d.supported T ht\n    refine Finset.ssubset_iff_subset_ne.mpr ⟨hs, ?_⟩\n    intro he\n    let z : Label m := ⟨3, by omega⟩\n    have hz : z ∈ T := by rw [he]; exact (tail_mem m hm z).mpr (by rfl)\n    have htail := (mem_pathIndependentOn _ T).mp ((mem_pathFamily _ T).mp ht)\n    have hn := (cyclePathTail_vertices m hm z).mp (htail.1 hz)\n    dsimp [z] at hn\n    omega\n  have hc := maximal_cells d.protected\n    (by intro T hT; exact ⟨d.protected_subset T hT, hp T hT⟩)\n    (by\n      intro T hT U hU hTU\n      apply path_critical_maximal _ (cyclePathTail_nodup m hm) T _ U hU hTU\n      have h := (criticalFaces_mem _ T).mp hT\n      simpa only [d, zeroContract, maximalContract, cycleTailWordData, pathWordData_word] using h)\n  refine {\n    empty_mem := ?_\n    collar := A0 m hm\n    critical := d.protected.image (fun T => tailGround m hm \\ T)\n    contains := le_rfl\n    supported := by intro s hs; exact hs.2\n    critical_supported := ?_\n    cells := hd ▸ hc\n    main := d.protectedDualWordSequence.cast rfl ?_\n    separate := Sequence.refl _ }\n  · rw [← hd, dual_mem]\n    refine ⟨Finset.empty_subset _, ?_⟩\n    intro h\n    have ht := (mem_pathIndependentOn _ _).mp ((mem_pathFamily _ _).mp h)\n    let z : Label m := ⟨3, by omega⟩\n    have hz : z ∈ tailGround m hm := (tail_mem m hm z).mpr (by rfl)\n    have hn := (cyclePathTail_vertices m hm z).mp\n      (ht.1 (by simpa only [Finset.sdiff_empty] using hz))\n    dsimp [z] at hn\n    omega\n  · intro s hs\n    obtain ⟨T, _, rfl⟩ := Finset.mem_image.mp hs\n    exact Finset.sdiff_subset\n  · change project (rawEndpoint _ _ _ _) = _\n    rw [contract_endpoint d, hd]\n\n/-- Exact zero critical tops, including singleton complements of empty tails. -/", DescribeRole.Definition),
            Node("fill0_critical", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem fill0_critical (m : Nat) (hm : 3 ≤ m) :\n    (fill0 m hm).critical = if m % 3 = 2 then ∅ else {eta0 m hm}", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill0_critical\ntheorem fill0_critical (m : Nat) (hm : 3 ≤ m) :\n    (fill0 m hm).critical = if m % 3 = 2 then ∅ else {eta0 m hm} := by\n  change (criticalFaces (tailWord m hm)).image (fun T => tailGround m hm \\ T) = _\n  rw [tailWord_critical_formula]\n  split_ifs <;> simp [eta0]\n\n/-- P01's dual on Z keeps both forbidden endpoint ghosts. -/", DescribeRole.Theorem, describeId: "fill0-critical"),
            Node("A0_rawDual", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem A0_rawDual (m : Nat) (hm : 3 ≤ m) :\n    rawDual (tailGround m hm) (pathFamily (cyclePathTail m hm)) = A0 m hm", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.A0_rawDual\ntheorem A0_rawDual (m : Nat) (hm : 3 ≤ m) :\n    rawDual (tailGround m hm) (pathFamily (cyclePathTail m hm)) = A0 m hm :=\n  zero_dual m hm", DescribeRole.Theorem, describeId: "a0-raw-dual"),
            Node("wheelRoot_eq_A1", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem wheelRoot_eq_A1 (m : Nat) (hm : 3 ≤ m) :\n    wheelRoot m (by omega) = A1 m hm", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.wheelRoot_eq_A1\ntheorem wheelRoot_eq_A1 (m : Nat) (hm : 3 ≤ m) :\n    wheelRoot m (by omega) = A1 m hm := by\n  apply SetLike.ext\n  intro s\n  change (∃ i : Fin m, s ⊆ ground m \\ rimEdge m (by omega) i) ↔\n    (∃ i : {i : Fin m // i ≠ interfaceRow m hm},\n      s ⊆ ground m \\ rimEdge m (by omega) i.val) ∨ s ⊆ tailGround m hm\n  constructor\n  · rintro ⟨i, hi⟩\n    by_cases he : i = interfaceRow m hm\n    · right\n      simpa only [he, interface_edge, tailGround] using hi\n    · exact Or.inl ⟨⟨i, he⟩, hi⟩\n  · rintro (⟨i, hi⟩ | hi)\n    · exact ⟨i.val, hi⟩\n    · exact ⟨interfaceRow m hm, by simpa only [interface_edge, tailGround] using hi⟩", DescribeRole.Theorem, describeId: "wheel-root-eq-a1"),
            Node("excludedCycleContract", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef excludedCycleContract (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    Contract (ground m) (facets (cycleIndependentOn m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.excludedCycleContract\ndef excludedCycleContract (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    Contract (ground m) (facets (cycleIndependentOn m hm)) :=\n  maximalContract (cycleWordData m hm) (by\n    intro S hS U hU hSU\n    exact cycle_critical_maximal m hm hr S hS U hU hSU)\n    (by intro L v h; exact cycle_face_proper m hm _ ((cycleWordData m hm).pair_data L v h).2.1)\n\n/-- Genuine P06 filling in residues zero and two, with collar exactly A1,\n    all proper critical boundaries, and the separate identity list. -/", DescribeRole.Definition, describeId: "excluded-cycle-contract"),
            Node("fill1Excluded", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef fill1Excluded (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    Filling (ground m) (A1 m hm)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill1Excluded\ndef fill1Excluded (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    Filling (ground m) (A1 m hm) := by\n  let d := excludedCycleContract m hm hr\n  have hd : rawDual (ground m) (facets (cycleIndependentOn m hm)) = A1 m hm :=\n    (cycleWord_rawDual_eq_wheelRoot m hm).trans (wheelRoot_eq_A1 m hm)\n  have hc := maximal_cells d.protected\n    (by intro T hT; exact ⟨d.protected_subset T hT,\n      cycle_face_proper m hm T (d.protected_subset T hT)⟩)\n    (by intro T hT U hU hTU\n        exact cycle_critical_maximal m hm hr T ((criticalFaces_mem _ T).mp hT) U hU hTU)\n  refine {\n    empty_mem := ?_\n    collar := A1 m hm\n    critical := d.protected.image (fun T => ground m \\ T)\n    contains := le_rfl\n    supported := by intro s hs; rw [← wheelRoot_eq_A1 m hm] at hs\n                    exact (rimRows m (by omega)).root_supported s hs\n    critical_supported := ?_\n    cells := hd ▸ hc\n    main := d.protectedDualWordSequence.cast rfl ?_\n    separate := Sequence.refl _ }\n  · rw [← hd, dual_mem]\n    refine ⟨Finset.empty_subset _, ?_⟩\n    intro h\n    have hp := cycle_face_proper m hm _ h\n    simp only [Finset.sdiff_empty] at hp\n    exact hp.ne rfl\n  · intro s hs\n    obtain ⟨T, _, rfl⟩ := Finset.mem_image.mp hs\n    exact Finset.sdiff_subset\n  · change project (rawEndpoint _ _ _ _) = _\n    rw [contract_endpoint d, hd]\n\n/-- The exact two/one critical tops use fixed-ground cycle complements. -/", DescribeRole.Definition, describeId: "fill1-excluded"),
            Node("fill1Excluded_critical", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem fill1Excluded_critical (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    (fill1Excluded m hm hr).critical = cycleCritical m hm", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill1Excluded_critical\ntheorem fill1Excluded_critical (m : Nat) (hm : 3 ≤ m) (hr : m % 3 ≠ 1) :\n    (fill1Excluded m hm hr).critical = cycleCritical m hm := by\n  exact (cycleCritical_eq_complements m hm).symm\n\n/- A pivot changes from the earlier residue lo+1 to the later residue lo.\n   This finite set is only arithmetic notation used in the EXISTING Word. -/", DescribeRole.Theorem, describeId: "fill1-excluded-critical"),
            Node("collarA", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarA (m : Nat) (j : Fin (m/3)) : Finset (Label m)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarA\ndef collarA (m : Nat) (j : Fin (m/3)) : Finset (Label m) :=\n  insert (lastLabel m) (switchBase m 2 (m/3) j.val)", DescribeRole.Definition, describeId: "collar-a"),
            Node("collarPivot", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarPivot (m : Nat) (j : Fin (m/3)) : Label m", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarPivot\ndef collarPivot (m : Nat) (j : Fin (m/3)) : Label m :=\n  ⟨3*j.val+2, by have := j.isLt; omega⟩", DescribeRole.Definition, describeId: "collar-pivot"),
            Node("collarB", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarB (m : Nat) (j : Fin (m/3)) : Finset (Label m)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarB\ndef collarB (m : Nat) (j : Fin (m/3)) : Finset (Label m) :=\n  insert (collarPivot m j) (collarA m j)", DescribeRole.Definition, describeId: "collar-b"),
            Node("collarUpper", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarUpper (m : Nat) (j : Fin (m/3)) : Finset (Label m)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarUpper\ndef collarUpper (m : Nat) (j : Fin (m/3)) : Finset (Label m) := ground m \\ collarA m j", DescribeRole.Definition, describeId: "collar-upper"),
            Node("collarLower", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarLower (m : Nat) (j : Fin (m/3)) : Finset (Label m)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarLower\ndef collarLower (m : Nat) (j : Fin (m/3)) : Finset (Label m) := ground m \\ collarB m j", DescribeRole.Definition, describeId: "collar-lower"),
            Node("goodH", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef goodH (m : Nat) : Finset (Finset (Label m))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.goodH\ndef goodH (m : Nat) : Finset (Finset (Label m)) :=\n  insert (labelsCongruent m 2 2)\n    ((Finset.univ : Finset (Fin (m/3))).biUnion (fun j => {collarA m j, collarB m j}))", DescribeRole.Definition, describeId: "good-h"),
            Node("goodCycleContract", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef goodCycleContract (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Contract (ground m) (facets (cycleIndependentOn m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.goodCycleContract\ndef goodCycleContract (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Contract (ground m) (facets (cycleIndependentOn m hm)) where\n  toWord := cycleWordData m hm\n  protected := goodH m\n  protected_subset := by\n    intro T hT\n    rcases (mem_goodH m T).mp hT with rfl | ⟨j, rfl | rfl⟩\n    · exact (cycleWordData m hm).critical_data _ (good_critical m hm h1)\n    · exact (collar_pair_data m hm h1 j).1\n    · exact (collar_pair_data m hm h1 j).2.1\n  protected_upward := by\n    intro T U hT hU hTU\n    apply (mem_goodH m U).mpr\n    rcases (mem_goodH m T).mp hT with rfl | ⟨j, rfl | rfl⟩\n    · rcases critical_supersets m hm h1 U hU hTU with he | he\n      · exact Or.inl he\n      · exact Or.inr ⟨⟨0, good_k m hm h1⟩, Or.inr he⟩\n    all_goals\n      have haU : collarA m j ⊆ U := by\n        first | exact hTU | exact (Finset.subset_insert _ _).trans hTU\n      rcases collar_supersets m hm h1 j U hU haU with he | he | ⟨hj, he⟩\n      · exact Or.inr ⟨j, Or.inl he⟩\n      · exact Or.inr ⟨j, Or.inr he⟩\n      · exact Or.inr ⟨⟨j.val+1, hj⟩, Or.inr he⟩\n  protected_pair := by\n    intro L v hp\n    have whole : ∀ T ∈ (Symbol.pair L v).faces, T ∈ goodH m →\n        ∀ U ∈ (Symbol.pair L v).faces, U ∈ goodH m := by\n      intro T hT hH U hU\n      rcases (mem_goodH m T).mp hH with he | ⟨j, he | he⟩\n      · have ho := word_owner (cycleWordData m hm).partition hp (good_critical m hm h1)\n          hT (by simpa only [he, Symbol.faces, Finset.mem_singleton])\n        cases ho\n      all_goals\n        have ht : T ∈ (Symbol.pair (collarA m j) (collarPivot m j)).faces := by\n          simp [Symbol.faces, he, collarB]\n        have ho := word_owner (cycleWordData m hm).partition hp\n          (collar_pair_in_word m hm h1 j) hT ht\n        rw [ho] at hU\n        rcases (show U = collarA m j ∨ U = collarB m j by\n          simpa only [Symbol.faces, Finset.mem_insert, Finset.mem_singleton, collarB] using hU)\n          with he | he\n        · exact (mem_goodH m U).mpr (Or.inr ⟨j, Or.inl he⟩)\n        · exact (mem_goodH m U).mpr (Or.inr ⟨j, Or.inr he⟩)\n    exact ⟨fun h => whole L (by simp [Symbol.faces]) h _ (by simp [Symbol.faces]),\n      fun h => whole (insert v L) (by simp [Symbol.faces]) h _ (by simp [Symbol.faces])⟩\n  critical_protected := by\n    intro S hS\n    have hc := (criticalFaces_mem _ S).mpr hS\n    rw [cycleWord_critical_formula, if_neg (by omega : m % 3 ≠ 0), if_pos h1] at hc\n    exact (mem_goodH m S).mpr (Or.inl (Finset.mem_singleton.mp hc))\n  emitted_proper := by\n    intro L v hp _\n    exact cycle_face_proper m hm _ ((cycleWordData m hm).pair_data L v hp).2.1\n\n/-- Standalone B1, without the retained eta1 simplex. -/", DescribeRole.Definition, describeId: "good-cycle-contract"),
            Node("collarCore", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarCore (m : Nat) (hm : 3 ≤ m) : Family (Label m)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarCore\ndef collarCore (m : Nat) (hm : 3 ≤ m) : Family (Label m) :=\n  A1 m hm ⊔ facets ((Finset.univ : Finset (Fin (m/3))).image (collarUpper m))", DescribeRole.Definition, describeId: "collar-core"),
            Node("collarSequence", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef collarSequence (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Sequence (project (collarCore m hm)) (project (A1 m hm))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.collarSequence\ndef collarSequence (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Sequence (project (collarCore m hm)) (project (A1 m hm)) :=\n  (collarFrom m hm h1 0 (Nat.zero_le _)).cast\n    (congrArg project (collarState_start m hm h1)) rfl\n\n/-- Good-class fill1 with actual main list, exact critical eta1 and the\n    SEPARATE collar just constructed. -/", DescribeRole.Definition, describeId: "collar-sequence"),
            Node("fill1Good", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef fill1Good (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Filling (ground m) (A1 m hm)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill1Good\ndef fill1Good (m : Nat) (hm : 3 ≤ m) (h1 : m % 3 = 1) :\n    Filling (ground m) (A1 m hm) where\n  empty_mem := by\n    rw [← good_dual m hm, dual_mem]\n    refine ⟨Finset.empty_subset _, ?_⟩\n    intro h\n    have hp := cycle_face_proper m hm _ h\n    simp only [Finset.sdiff_empty] at hp\n    exact hp.ne rfl\n  collar := collarCore m hm\n  critical := {eta1 m hm}\n  contains := le_sup_left\n  supported := by\n    intro s hs\n    rcases hs with hs | ⟨t, ht, hst⟩\n    · rw [← wheelRoot_eq_A1 m hm] at hs\n      exact (rimRows m (by omega)).root_supported s hs\n    · obtain ⟨i, _, rfl⟩ := Finset.mem_image.mp ht\n      exact hst.trans Finset.sdiff_subset\n  critical_supported := by intro s hs; rw [Finset.mem_singleton.mp hs]; exact Finset.sdiff_subset\n  cells := eta_good_cells m hm h1\n  main := (goodCycleContract m hm h1).protectedDualWordSequence.cast rfl\n    (congrArg project (good_endpoint m hm h1))\n  separate := collarSequence m hm h1\n\n/-- Both residues and the collar residue share the original Filling API;\n    none of the desired outputs is an input to this all-m function. -/", DescribeRole.Definition, describeId: "fill1-good"),
            Node("fill1", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef fill1 (m : Nat) (hm : 3 ≤ m) : Filling (ground m) (A1 m hm)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill1\ndef fill1 (m : Nat) (hm : 3 ≤ m) : Filling (ground m) (A1 m hm) :=\n  if h1 : m % 3 = 1 then fill1Good m hm h1 else fill1Excluded m hm h1", DescribeRole.Definition),
            Node("fill1_critical", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem fill1_critical (m : Nat) (hm : 3 ≤ m) :\n    (fill1 m hm).critical = cycleCritical m hm", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.fill1_critical\ntheorem fill1_critical (m : Nat) (hm : 3 ≤ m) :\n    (fill1 m hm).critical = cycleCritical m hm := by\n  unfold fill1\n  split_ifs with h1\n  · simp only [fill1Good, cycleCritical, if_neg (by omega : m % 3 ≠ 0), if_pos h1, eta1]\n  · exact fill1Excluded_critical m hm h1", DescribeRole.Theorem, describeId: "fill1-critical"),
            Node("pathFilling_critical", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem pathFilling_critical (m : Nat) (hm : 3 ≤ m) :\n    (pathFilling m hm).critical =\n      if m % 3 = 1 then ∅ else\n        {ground m \\ FiniteIndependentPathGreedy.pathChosen (pathRootPath m hm)}", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.pathFilling_critical\ntheorem pathFilling_critical (m : Nat) (hm : 3 ≤ m) :\n    (pathFilling m hm).critical =\n      if m % 3 = 1 then ∅ else\n        {ground m \\ FiniteIndependentPathGreedy.pathChosen (pathRootPath m hm)} := by\n  change (criticalFaces (pathRootWordData m hm).word).image (fun T => ground m \\ T) = _\n  rw [root_word, pathWord_critical_formula _ (pathRootPath_nodup m hm), pathRootPath_length]\n  split_ifs <;> simp\n\n/-- Necessity includes BOTH excluded residues. It uses ordinary finite Euler\n    invariance and the actual one-critical partial filling; no homology or\n    inferred collapse from a contractible target is used. -/", DescribeRole.Theorem, describeId: "path-filling-critical"),
            Node("gamma_iff", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen FiniteProtectedDualWord OriginalLabelTwoSum\nopen FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nopen scoped BigOperators\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem gamma_iff (m : Nat) (hm : 3 ≤ m) :\n    Nonempty (Sequence (project (delta (ground m))) (project (pathRoot m hm))) ↔\n      goodResidue m", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Protected.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.gamma_iff\ntheorem gamma_iff (m : Nat) (hm : 3 ≤ m) :\n    Nonempty (Sequence (project (delta (ground m))) (project (pathRoot m hm))) ↔\n      goodResidue m := by\n  constructor\n  · rintro ⟨G⟩\n    by_contra hn\n    have hr : m % 3 ≠ 1 := by\n      intro h1\n      exact hn ⟨m/3, good_width m h1⟩\n    let d := ground m \\ FiniteIndependentPathGreedy.pathChosen (pathRootPath m hm)\n    have hc : (pathFilling m hm).critical = {d} := by\n      rw [pathFilling_critical, if_neg hr]\n    have hmain := sequence_euler (pathFilling m hm).main\n    have hgamma := sequence_euler G\n    have hcells : CriticalData (pathRoot m hm) {d} := by\n      rw [← hc]\n      exact (pathFilling m hm).cells\n    have hcell := cell_euler (pathRoot m hm) d hcells\n    change nativeEuler (project (delta (ground m))) =\n      nativeEuler (project (endpoint (pathRoot m hm) (pathFilling m hm).critical)) at hmain\n    rw [hc] at hmain\n    have hzero : (-1 : Int)^d.card = 0 := by omega\n    exact (pow_ne_zero d.card (by decide : (-1 : Int) ≠ 0)) hzero\n  · intro hg\n    exact ⟨gammaGood m hm hg⟩", DescribeRole.Theorem, describeId: "gamma-iff"))));
